    return FfiConverterTypeStorageKey.lower(value)
}




/**
 * A board account, as `zGetAccount` exports it.
 */
public struct Account {
    public var index: UInt32
    public var network: Network
    /**
     * 32 bytes.
     */
    public var seedFingerprint: Data
    /**
     * Orchard + P2PKH UFVK.
     */
    public var ufvk: String
    public var ua: String
    public var tAddress: String
    public var birthday: UInt32?
    /**
     * What to import it with: `KEY_SOURCE` ("leekwallet").
     */
    public var keySource: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(index: UInt32, network: Network, 
        /**
         * 32 bytes.
         */seedFingerprint: Data, 
        /**
         * Orchard + P2PKH UFVK.
         */ufvk: String, ua: String, tAddress: String, birthday: UInt32?, 
        /**
         * What to import it with: `KEY_SOURCE` ("leekwallet").
         */keySource: String) {
        self.index = index
        self.network = network
        self.seedFingerprint = seedFingerprint
        self.ufvk = ufvk
        self.ua = ua
        self.tAddress = tAddress
        self.birthday = birthday
        self.keySource = keySource
    }
}

