extension Account: Sendable {}
#endif


extension Account: Equatable, Hashable {
    public static func ==(lhs: Account, rhs: Account) -> Bool {
        if lhs.index != rhs.index {
            return false
        }
        if lhs.network != rhs.network {
            return false
        }
        if lhs.seedFingerprint != rhs.seedFingerprint {
            return false
        }
        if lhs.ufvk != rhs.ufvk {
            return false
        }
        if lhs.ua != rhs.ua {
            return false
        }
        if lhs.tAddress != rhs.tAddress {
            return false
        }
        if lhs.birthday != rhs.birthday {
            return false
        }
        if lhs.keySource != rhs.keySource {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(index)
        hasher.combine(network)
        hasher.combine(seedFingerprint)
        hasher.combine(ufvk)
        hasher.combine(ua)
        hasher.combine(tAddress)
        hasher.combine(birthday)
        hasher.combine(keySource)
    }
}



