extension SdRequest: Sendable {}
#endif


extension SdRequest: Equatable, Hashable {
    public static func ==(lhs: SdRequest, rhs: SdRequest) -> Bool {
        if lhs.fileName != rhs.fileName {
            return false
        }
        if lhs.zsigFileName != rhs.zsigFileName {
            return false
        }
        if lhs.bytes != rhs.bytes {
            return false
        }
        if lhs.sentHash != rhs.sentHash {
            return false
        }
        if lhs.account != rhs.account {
            return false
        }
        if lhs.network != rhs.network {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(fileName)
        hasher.combine(zsigFileName)
        hasher.combine(bytes)
        hasher.combine(sentHash)
        hasher.combine(account)
        hasher.combine(network)
    }
}



