/**
 * What the board signed.
 *
 * Persist `record` (or `signed_pczt` and `txid`) before broadcasting; read
 * it back with [`sign_result_from_bytes`].
 */
public struct SignResult {
    /**
     * The wallet's PCZT with the board's signatures applied and verified:
     * hand it to the wallet's Keystone path (prove, extract).
     */
    public var signedPczt: Data
    /**
     * 32 bytes: the shielded sighash the user reviewed on the board.
     */
    public var sighash: Data
    /**
     * The signatures as a `.zsig` file.
     */
    public var zsig: Data
    /**
     * How many signatures the board returned.
     */
    public var signatureCount: UInt32
    /**
     * 32 bytes, internal order: final before proving (ZIP 244).
     */
    public var txid: Data
    /**
     * The txid as explorers and lightwalletd show it.
     */
    public var txidHex: String
    /**
     * All of the above as one record (`SignResult::to_bytes`).
     */
    public var record: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The wallet's PCZT with the board's signatures applied and verified:
         * hand it to the wallet's Keystone path (prove, extract).
         */signedPczt: Data, 
        /**
         * 32 bytes: the shielded sighash the user reviewed on the board.
         */sighash: Data, 
        /**
         * The signatures as a `.zsig` file.
         */zsig: Data, 
        /**
         * How many signatures the board returned.
         */signatureCount: UInt32, 
        /**
         * 32 bytes, internal order: final before proving (ZIP 244).
         */txid: Data, 
        /**
         * The txid as explorers and lightwalletd show it.
         */txidHex: String, 
        /**
         * All of the above as one record (`SignResult::to_bytes`).
         */record: Data) {
        self.signedPczt = signedPczt
        self.sighash = sighash
        self.zsig = zsig
        self.signatureCount = signatureCount
        self.txid = txid
        self.txidHex = txidHex
        self.record = record
    }
}

#if compiler(>=6)
extension SignResult: Sendable {}
#endif


extension SignResult: Equatable, Hashable {
    public static func ==(lhs: SignResult, rhs: SignResult) -> Bool {
        if lhs.signedPczt != rhs.signedPczt {
            return false
        }
        if lhs.sighash != rhs.sighash {
            return false
        }
        if lhs.zsig != rhs.zsig {
            return false
        }
        if lhs.signatureCount != rhs.signatureCount {
            return false
        }
        if lhs.txid != rhs.txid {
            return false
        }
        if lhs.txidHex != rhs.txidHex {
            return false
        }
        if lhs.record != rhs.record {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(signedPczt)
        hasher.combine(sighash)
        hasher.combine(zsig)
        hasher.combine(signatureCount)
        hasher.combine(txid)
        hasher.combine(txidHex)
        hasher.combine(record)
    }
}



