/**
 * Every error, by the hundreds digit of its stable `code`.
 *
 * `code` is `leek_zcash::LeekError::code` (the README lists them),
 * `recovery` its `Recovery`, `reason` a fixed sentence per code that never
 * carries an amount, an address, a key or PCZT bytes, so it can go to logs.
 * `device_code` is the firmware's code when the board refused with one this
 * version does not know (`code` 900).
 */
public enum LeekError: Swift.Error {

    
    
    /**
     * 1xx: the link (not found, permission, dropped, timeout, cancelled).
     */
    case Link(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 2xx: the session and the board's state (pairing, locked, busy, ...).
     */
    case Session(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 3xx: the user said no, or did not answer, on the board.
     */
    case User(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 4xx: account and network.
     */
    case Account(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 5xx: the PCZT (unsupported, too large, does not parse, ...).
     */
    case Pczt(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 6xx: the signatures (`.zsig` for other bytes, a bad signature, ...).
     */
    case Signature(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 7xx: stored app data (an invalid app identifier, data sealed for
     * another key, damaged data, a forgotten Storage Key).
     */
    case Storage(code: UInt16, recovery: Recovery, reason: String
    )
    /**
     * 9xx: a firmware error code this version does not know.
     */
    case Device(code: UInt16, recovery: Recovery, reason: String, deviceCode: UInt16
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLeekError: FfiConverterRustBuffer {
    typealias SwiftType = LeekError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LeekError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Link(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Session(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .User(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Account(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Pczt(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Signature(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Storage(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Device(
            code: try FfiConverterUInt16.read(from: &buf), 
            recovery: try FfiConverterTypeRecovery.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf), 
            deviceCode: try FfiConverterUInt16.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LeekError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Link(code,recovery,reason):
            writeInt(&buf, Int32(1))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Session(code,recovery,reason):
            writeInt(&buf, Int32(2))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .User(code,recovery,reason):
            writeInt(&buf, Int32(3))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Account(code,recovery,reason):
            writeInt(&buf, Int32(4))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Pczt(code,recovery,reason):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Signature(code,recovery,reason):
            writeInt(&buf, Int32(6))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(code,recovery,reason):
            writeInt(&buf, Int32(7))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Device(code,recovery,reason,deviceCode):
            writeInt(&buf, Int32(8))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterTypeRecovery.write(recovery, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterUInt16.write(deviceCode, into: &buf)
            
        }
    }
}


